                        .set("useEvent", use)
                        .set("canRepeat", repeat)
                        .set("ai", function () {
                            const evt = get.event();
                            return lib.skill.csh_juwei.ai.choose(evt.useEvent, evt.player, evt.canRepeat);
                        }).forResult();
                    event.result = { bool: controls.includes(result.control) && result.control !== "cancel2", cost_data: result.control };
                }

