                            if (!target || !get.tag(card, "damage")) return;
                            if (!target.hasSkill("csh_zili")) return;
                            if (get.attitude(player, target) <= 0) return;
                            var n = 0;
                            try {
                                n = target.getExpansions("xinquanji").length;
                            } catch (e) {}
                            if (n > 3) return;
                            if (n === 3) return [1, 1.6];
                            if (n >= 1) return [1, 0.9];
                            return [1, 0.35];
                        },
                    },
                    skillTagFilter(player, tag, arg) {
                        if (tag !== "maixie" && tag !== "maixie_hp") return;
                        try {
                            var evt = _status.event;
                            var source = evt && evt.player;
                            // 队友：权未叠满时允许「助觉醒」向的卖血；已可觉醒/已觉醒则关掉
                            if (source && source !== player && get.attitude(source, player) > 0) {
                                if (!player.hasSkill("csh_zili")) return false;
                                var qn = player.getExpansions("xinquanji").length;
                                if (qn > 3) return false;
                                // 权≤3：保留 maixie，方便队友补刀叠权
                                return;
                            }
                            // 面对【杀】且有闪：关掉卖血，优先出闪（挑衅叠权更赚）
                            if (evt && (evt.name === "sha" || (evt.card && evt.card.name === "sha") || evt.name === "chooseToUse" || evt.name === "chooseToRespond")) {
                                var card = evt.card || (evt.getParent && evt.getParent().card);
                                if (card && card.name === "sha") {
                                    if (typeof player.hasShan === "function" && player.hasShan()) return false;
                                    if (player.countCards("h", "shan") > 0) return false;
                                }
                            }
                        } catch (e) {}
                    },
                    effect: {
                        target: function (card, player, target) {
                            if (!card) return;
                            // 队友：不加卖血正分、也不额外惩罚 → 完全默认评估（该打打、不该打不打）
                            if (get.attitude(player, target) > 0) return;
                            // —— 以下仅敌人 ——
                            if (card.name === "sha") {
                                var needQuan =
                                    target.hasSkill("csh_zhonghui_tiaoxin") &&
                                    target.hasSkill("csh_zili") &&
                                    target.getExpansions("xinquanji").length < 4;
                                var hasShan =
                                    (typeof target.hasShan === "function" && target.hasShan()) ||
                                    target.countCards("h", "shan") > 0;
                                if (needQuan && hasShan) {
                                    // 有闪：不鼓励吃杀，默认优先出闪
                                    return;
                                }
                                if (needQuan && !hasShan && target.hp > 1) {
                                    if (player.hasSkillTag("jueqing", false, target)) return [1, -2];
                                    return [1, 0.6];
                                }
                            }
                            if (get.tag(card, "damage")) {
                                if (player.hasSkillTag("jueqing", false, target)) return [1, -2];
                                if (!target.hasFriend()) return;
                                if (target.hp >= 4) return [0.5, get.tag(card, "damage") * 2];
                                if (!target.hasSkill("csh_xinpaiyi") && !target.hasSkill("xinpaiyi") && target.hp > 1) {
                                    return [0.5, get.tag(card, "damage") * 1.5];
                                }
                                if (target.hp == 3) return [0.5, get.tag(card, "damage") * 1.5];
                                if (target.hp == 2) return [1, get.tag(card, "damage") * 0.5];
                            }
                        },
                    },
                }

