details.cost:
(event, trigger, player) {
                    const num = player.storage.csh_liegong_xian || 0;
                    const target = trigger.target;
                    event.result = await player
                        .chooseBool(get.prompt("csh_liegong"), "是否释放全部 " + num + " 点弦？")
                        .set("ai", function () {
                            const evt = get.event();
                            const player = evt.player, target = evt.target, num = evt.num;
                            if (get.attitude(player, target) > 0) return false;
                            let dmg = 1;
                            if (num >= 45) dmg++;
                            if (num >= 75) dmg++;
                            if (num >= 95) dmg++;
                            if (target.hp <= dmg && (num >= 15 || !target.hasShan())) return true;
                            if (num >= 65) return true;
                            if (!player.storage.csh_liegong_m100 && num >= 45) return false;
                            if (!player.storage.csh_liegong_m50 && num < 50) return false;
                            if (num >= 75 && get.attitude(player, target) < -1) return true;
                            if (num >= 55 && target.hp <= 2) return true;
                            return false;
                        })
                        .set("num", num)
                        .set("target", target)
                        .forResult();
                }

