details.check:
function (card) {
                    // 联机安全：全 try，禁止 card.suit / game.currentPlayer 等易空引用
                    try {
                        var player = _status.event.player;
                        if (!player || !card) return 0;
                        var baseScore = 8 - get.value(card);
                        var suit = get.suit(card, player);
                        var num = get.number(card, player);
                        var enemies = game.filterPlayer(function (current) {
                            try {
                                if (!current || current === player) return false;
                                if (current.getExpansions && current.getExpansions("csh_rezhoufu_judge").length) return false;
                                return get.attitude(player, current) < 0;
                            } catch (e) {
                                return false;
                            }
                        });
                        if (!enemies.length) return baseScore;
                        // 有延时锦囊时，优先选能改判的花色
                        for (var i = 0; i < enemies.length; i++) {
                            var t = enemies[i];
                            var judges = [];
                            try {
                                if (t.getCards) judges = t.getCards("j") || [];
                                else if (t.judging) judges = t.judging || [];
                            } catch (e) {}
                            for (var j = 0; j < judges.length; j++) {
                                var judge = judges[j];
                                if (!judge) continue;
                                var jn = get.name(judge);
                                if (jn === "lebusishu" && suit === "heart") return baseScore + 12;
                                if (jn === "bingliangcunduan" && suit === "club") return baseScore + 12;
                                if (jn === "shandian" && suit === "spade" && num >= 2 && num <= 9) return baseScore + 12;
                            }
                        }
                        return baseScore;
                    } catch (e) {
                        return 1;
                    }
                }

