                        player: 1,
                        target: function (player, target) {
                            // 有害技：对敌人给负分（配合态度得正收益）；队友默认不选
                            try {
                                if (!player || !target || target === player) return 0;
                                if (target.getExpansions && target.getExpansions("csh_rezhoufu_judge").length) return 0;
                                var att = get.attitude(player, target);
                                // —— 队友：默认绝不挂；唯一例外：判定区有乐且自己有红桃（用咒改判定解乐）——
                                if (att >= 0) {
                                    var hasLebu = false;
                                    try {
                                        if (typeof target.hasJudge === "function" && target.hasJudge("lebusishu")) hasLebu = true;
                                        else if (target.getCards) hasLebu = target.getCards("j", function (c) { return get.name(c) === "lebusishu"; }).length > 0;
                                    } catch (e) {}
                                    var hasHeart = false;
                                    try {
                                        hasHeart = player.countCards("he", function (c) {
                                            try { return get.suit(c, player) === "heart"; } catch (e2) { return false; }
                                        }) > 0;
                                    } catch (e) {}
                                    if (hasLebu && hasHeart) return 1.2; // 解乐：对队友偏正
                                    return 0; // 不选队友
                                }
                                // —— 敌人：无脑挂，残血/有判定/手牌多优先 ——
                                var score = 2.5;
                                try {
                                    if (target.hp <= 2) score += 1.2;
                                    else if (target.hp <= target.maxHp / 2) score += 0.6;
                                } catch (e) {}
                                try {
                                    var jl = target.getCards ? target.getCards("j").length : (target.judging ? target.judging.length : 0);
                                    if (jl > 0) score += 1;
                                } catch (e) {}
                                try {
                                    if (target.countCards("h") > 3) score += 0.4;
                                } catch (e) {}
                                try {
                                    if (_status.currentPhase === target) score += 0.3;
                                } catch (e) {}
