(event, trigger, player) {
                    const num1 = player.countCards("h");
                    const num2 = trigger.source.countCards("h");
                    if (num1 > num2) {
                        // 弃置来源手牌数张，再造成1点伤害
                        if (num2 <= 0) {
                            event.result = { bool: true, cost_data: "discard", cards: [] };
                            return;
                        }
                        const result = await player
                            .chooseToDiscard("h", num2, "chooseonly")
                            .set("prompt", get.prompt("csh_benyu", trigger.source))
                            .set("prompt2", "弃置" + get.cnNumber(num2) + "张手牌，对" + get.translation(trigger.source) + "造成1点伤害")
                            .set("ai", function (card) {
                                const trigger = get.event().getTrigger();
                                const player = get.event().player;
                                const num = get.event().num2;
                                if (ui.selected.cards.length >= num) return -1;
                                if (get.damageEffect(trigger.source, player, player) > 0) {
                                    return 8 - get.value(card);
                                }
                                return -1;
                            })
                            .set("num2", num2)
                            .forResult();
                        if (result && result.bool && result.cards && result.cards.length) {
                            event.result = { bool: true, cards: result.cards, cost_data: "discard" };
                        } else {
                            event.result = { bool: false };
                        }
                    } else {
                        // 拼点，赢则+1护甲
                        const result = await player
                            .chooseBool(get.prompt("csh_benyu", trigger.source), "与其拼点，若你赢，你获得1点护甲")
