                            // 鼓励同时点队友与敌人：连接博弈
                            let score = 3;
                            if (att > 0) {
                                // 队友：连接关键牌/回合内角色，便于联动
                                score += 4 + (target.countCards("h") > 2 ? 2 : 0);
                                if (target === _status.currentPhase) score += 3;
                            } else if (att < 0) {
                                // 敌人：优先多手牌、未连接者
                                score += 5 + target.countCards("h") * 0.8;
                                if (typeof target.countConnectedCards === "function") score += Math.max(0, 2 - target.countConnectedCards());
                            } else {
                                score += 2;
                            }
                            if (ui.selected.targets.includes(target)) return 0;
                            // 已选里最好已有敌有友，缺哪补哪
