                            const hasE = ui.selected.targets.some(t => get.attitude(player2, t) < 0);
                            if (att > 0 && !hasF) score += 6;
                            if (att < 0 && !hasE) score += 6;
                            return score;
                        }).forResult();
                    }
                }

