					for (const skinName in skins) {
						dsReg[libKey][skinName] = process(skins[skinName]);
						count++;
					}
				}
				log(`已注册 ${count} 套动态皮肤到 decadeUI.dynamicSkin（资源前缀 ${prefix}）`);
			}
		);
	}

