			log("已检测到十周年UI：", JSON.stringify(getInfo()));
		} else {
			// 不直接放弃：扩展加载顺序不可控，玩家也可能稍后才启用十周年UI；
			// 交给 whenReady 排队等待，始终未出现则超时静默放弃。
			log("尚未检测到十周年UI，注册请求转入排队（超时自动放弃，不影响游戏）");
