        }

        /** 池子休闲：一级＝页签，二级＝这里的卡片列表。点「开始」即开局（1 步）。 */
        function renderLobby(body) {
            var games = [];
            var planned = [];
            try { if (lib.cshGames && lib.cshGames.list) games = lib.cshGames.list() || []; } catch (eG) { games = []; }
            try { if (lib.cshGames && lib.cshGames.planned) planned = lib.cshGames.planned() || []; } catch (eP) { planned = []; }

            if (!games.length) {
                hint(body, "小游戏模块未加载（csh_games.js）。请确认扩展文件完整后重开面板。");
                return;
            }

            /* —— 内容区标题已删除（2026-10-03）。
               原来这里渲染一行居中的「池 子 休 闲」纯展示标题，与左侧页签重名 ——
               用户反馈「两个池子休闲，一个位置不对，一个多余」，统一只保留页签一处。
               CDK 彩蛋不受影响：触发器在「池子休闲」页签上（2.5 秒内连点 10 次），
               从来不在标题上（见 tabDefs 处与 config.js 说明）。 —— */

            /* 【2026-10-03 用户决定】「一行一款 + 右侧「开始」按钮」→ **等大按钮网格**。
               旧卡片是两段式（左侧名字、中间大片空白、右侧开始），既费纵向空间，
               又要求玩家先读卡、再瞄准那颗按钮 —— 手机上还得上下滑才能看全。
               成熟做法：**这张卡本身就是按钮**（整块可点、无独立「开始」、大小一致）。
               生涯大厅与四款游戏同格并列（它同样是入口），用胶囊标签区分类型。
               网格 auto-fill + minmax：列数由可用宽度自己算 —— 一套布局同时服务桌面与手机。 */
            /* ★ 数字格式化（2026-10-15 补）：**本文件此前没有 fmt**，生涯大厅卡那句
               `fmt(WS.fundSum)` 一直在抛 ReferenceError 被 try/catch 吞掉 ⇒
               「在场 N 人 · 桌面资金 X」中部行从来没显示过。现在提到面板作用域共用一份，
               写法与天下榜页（rank.html）一致（万/亿简写），卡上与榜上显示同一个样子。 */
            function fmt(n) {
                n = Math.floor(Number(n) || 0);
                if (n >= 100000000) return (n / 100000000).toFixed(2) + " 亿";
                if (n >= 10000) return (n / 10000).toFixed(2) + " 万";
                return String(n);
            }

            /* 卡片框体归属（2026-10-17 · 作者指令）：
               「德州斗地主 UNO 廿一点就统一，其他的做出来各具特色」。
               ⇒ 四款牌桌**共用**一套 gb-table（同毡面 / 同左斜条 / 同角落暗纹），
                 四张只靠右上角 tag 与文案区分；金鳞市、妖灵图鉴各给一套专属框体。
               ★ 生涯大厅 / 讨伐录 / 天下榜 / 行囊 的特色类仍在各自 IIFE 里手挂（不动）。
               ★ 纯加类、零 DOM 结构变化；样式见本文件注入 CSS 段（gb-table/gb-goldfish/gb-codex）。 */
            var GAMECLASS = {
                texas: "gb-table", doudizhu: "gb-table", blackjack: "gb-table", uno: "gb-table",
                goldfish: "gb-goldfish", codex: "gb-codex",
            };

            function gameButton(title, desc, tag, onClick, locked) {
                var b = document.createElement("button");
                b.type = "button";
                b.className = "csh-dbg-gamebtn" + (locked ? " locked" : "");
                var top = document.createElement("span");
                top.className = "gb-top";
                var nm = document.createElement("b");
                nm.className = "gb-name";
                nm.textContent = title;
                top.appendChild(nm);
                if (tag) {
                    var tg = document.createElement("i");
                    tg.className = "gb-tag";
                    tg.textContent = tag;
                    top.appendChild(tg);
                }
                var d = document.createElement("span");
                d.className = "gb-desc";
                d.textContent = desc;
                b.appendChild(top);
                b.appendChild(d);
                if (!locked) {
                    b.addEventListener("click", function (e) {
                        e.preventDefault();
                        e.stopPropagation();
                        onClick();
