                    var c = raw.charAt(i);
                    var good = /[A-Z0-9\-]/.test(c);
                    html += good ? escHtml(c) : '<i class="bad">' + escHtml(c) + "</i>";
                }
                mirror.innerHTML = html || "&nbsp;";
            }
            function escHtml(s) {
                return String(s).replace(/[&<>"]/g, function (m) {
                    return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[m];
                });
            }
