        /** 势力：lib.character[武将名][1] 为势力键（wei/shu/wu/qun/shen…），无键时退回原字符串 */
        var CAMP_ORDER = { wei: 0, shu: 1, wu: 2, qun: 3, shen: 4 };
        function campTextOf(charName) {
            var raw = "";
            try {
                var c = lib.character && lib.character[charName];
