            function cnFirst(a, b) {
                if (a.hasCn !== b.hasCn) return a.hasCn ? -1 : 1;
                return (a.name || a.id).localeCompare(b.name || b.id, "zh");
            }
            exact.sort(cnFirst); head.sort(cnFirst); mid.sort(cnFirst);
