                    game.saveConfig(PS_KEY, json); ok = true;
                } else if (lib.config) {
                    lib.config[PS_KEY] = json; ok = true;
                }
            } catch (eCfg) {}
            return ok;
        }
        function psStamp(ts) {
            if (!ts) return "未知时间";
            try {
                var d = new Date(ts);
                function p2(n) { return n < 10 ? "0" + n : String(n); }
