                    /* 断点续传（2.0）：登记/沿用本次扩展的下载清单，跨面板、跨重试沿用 */
                    var rs = resumeLoad();
                    if (!rs || rs.name !== entry.name || rs.repo !== entry.repo || (rs.dir || "") !== (entry.dir || "")) {
                        resumeSave({ name: entry.name, repo: entry.repo, dir: entry.dir || "", branch: man.branch, done: [], t: Date.now() });
                    }
