                    remoteVer(entry).then(function (rv) {
                        if (!rv) return;
                        var upd = have && typeof cshVerCmp === "function" && cshVerCmp(rv, have) > 0;
                        dsc.textContent = (entry.intro || "") +
                            (have ? "　（已装 v" + have + (upd ? " → 可更新 v" + rv : "") + "）" : "") +
                            (!have ? "　远端 v" + rv : "");
