            /* 【2026-10-02】把关闭入口暴露到节点上：closePanel() 直接点 ✕ 关面板时
               不经过 closePick()，会让 document 级 keydown 与整棵卡片 DOM 永久泄漏。
               有了 __close，closePanel() 就能统一走这里销毁（同 csh_interact 的
               box.__esc 写法）。 */
            ov.__close = closePick;
            function onKey(e) {
                if (e.key !== "Escape" && e.keyCode !== 27) return;
