                    var tEl = document.createElement("div");
                    tEl.className = "t";
                    tEl.textContent = (CARD_CATS.filter(function (c) { return c.key === it.type; })[0] || { name: "其他" }).name;
                    var iEl = document.createElement("div");
                    iEl.className = "i";
