                            var ab0 = BR.asBoss || {};
                            if ((ab0.win || 0) + (ab0.lose || 0) > 0) midTxt2 += " · 亲征 " + (ab0.win || 0) + " 胜";
                            if (BR.speed && BR.speed.all) midTxt2 += " · 最快 " + BR.speed.all + " 轮";
