				if (!r1 || r1.ok === false) { ackToGame(cmd, false, r1 || persistenceRefused()); return; }
				r1.ok = true;
				GUARD[gk1] = r1;
				cshTableAward();
				ackToGame("shell-settle", true, r1);
				selfCloseAfterSettle(r1);   /* ★ 2026-09-30：委托关窗时，结算落地即关壳 */
				return;
