		fr.setAttribute("frameborder", "0");
		fr.setAttribute("scrolling", "no");
		fr.setAttribute("allow", "autoplay; fullscreen");
		mid.appendChild(fr);

		/* 暂停遮罩 */
		var pz = document.createElement("div");
		pz.id = "csh-shell-pause";
