			if (rec.ok) {
				// 开关为关时必须显式说出来：技能 filter 会在播报前就拦下，一点日志都不留，
				// 「装好了却一点动静都没有」多半就是这个开关。
				logInfo("播报安装成功（" + why + "）" + (enabled() ? "" : " · 播报总开关当前为关"), rec.skills);
			} else {
