                ["games","场次"],
                ["win","胜"],
                ["lose","负"],
                ["winrate","胜率"],
                ["avgdamage","均伤"],
                ["avgkill","均杀"],
                ["avgdamaged","均受"],
                ["avggain","均摸"],
                ["avgdiscard","均弃"],
                ["del",""]
            ];
            html.push(secTitle("武将排行 · 第 "+(wr.page+1)+" / "+pages+" 页"));
            html.push('<table id="csh-wr-table">');
            html.push('<thead><tr>');
            for(var i=0;i<cols.length;i++){
                var c=cols[i];
