                {k:"整体胜率",v:tGames?fmtPct(tWin/tGames):"—",n:"加权（胜 ÷ 场次）",tone:tGames?toneOf(tWin/tGames):""},
                {k:"场均击杀",v:tGames?fmtNum(tKill/tGames):"—",n:"全榜合计 ÷ 场次"},
                {k:"当前首位",v:esc(cname(top.name)),n:"按当前排序",tone:"hi"}
