                ["games","场次"],
                ["win","胜"],
                ["lose","负"],
                ["winrate","胜率"],
                ["avgdamage","均伤"],
                ["avgkill","均杀"],
                ["avgdamaged","均受"],
                ["avggain","均摸"],
                ["avgdiscard","均弃"],
